package android.util; public class SparseIntArray { final SparseArray<Integer> a=new SparseArray<>(); public SparseIntArray(){} public SparseIntArray(int n){} public int get(int k){return get(k,0);} public int get(int k,int d){return a.get(k,d);} public void put(int k,int v){a.put(k,v);} public void append(int k,int v){a.put(k,v);} public void clear(){a.clear();} public int size(){return a.size();} public int keyAt(int i){return a.keyAt(i);} public int valueAt(int i){return a.valueAt(i);} public int indexOfKey(int k){return a.indexOfKey(k);} public void delete(int k){a.delete(k);} }
